package com.cattlefarm.admin.platform;
import jakarta.validation.constraints.*;import java.util.*;
public final class PlatformDtos{private PlatformDtos(){}public record Farm(String farmId,String farmName,String farmCode,String farmType,String contactName,String contactPhone,String status,String remark,int version){}public record UpdateFarm(@NotBlank String farmName,String contactName,String contactPhone,String remark,@NotNull Integer version){}public record Rule(String code,String name,String value,String valueType,String remark){}public record UpdateRules(@NotEmpty Map<String,@NotBlank String>values){}public record Dashboard(long inField,long pendingTasks,long overdueTasks,long healthAlerts,long pregnantCows,long dueSoon,long withdrawalRestricted,long todayMixingOrders){}public record DictType(String typeId,String typeCode,String typeName,String status){}public record DictItem(String itemId,String typeCode,String itemCode,String itemName,int sortNo,String status,String remark){}public record CreateDictItem(@NotBlank String typeCode,@NotBlank@Pattern(regexp="[A-Z0-9_]{2,50}")String itemCode,@NotBlank String itemName,Integer sortNo,String remark){}public record UpdateDictItem(@NotBlank String itemName,@NotBlank@Pattern(regexp="ENABLED|DISABLED")String status,Integer sortNo,String remark){} }
